<script setup>
import {computed} from 'vue'; import {Head,Link,useForm} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; import PageBanner from '../../Components/PageBanner.vue';
defineOptions({layout:AppLayout}); const p=defineProps({vendors:Array,store_url:String,index_url:String}); const f=useForm({vendor_id:'',notes:'',lines:[]}); const vendor=computed(()=>p.vendors.find(x=>x.id===f.vendor_id)); const select=()=>f.lines=(vendor.value?.items||[]).filter(x=>Number(x.suggestion)>0).map(x=>({enabled:true,item_id:x.id,quantity:x.suggestion})); const submit=()=>f.transform(d=>({...d,lines:d.lines.filter(x=>x.enabled).map(({item_id,quantity})=>({item_id,quantity}))})).post(p.store_url);
</script>
<template><Head title="Buat Refill"/><div class="units-page"><PageBanner title="Buat Vendor Refill" description="Saran sudah mengurangi stok tersedia dan refill yang masih berjalan." icon="truck"/><section class="surface-card form-card"><form class="form-card__body form-stack" @submit.prevent="submit"><div v-if="Object.keys(f.errors).length" class="field-error" role="alert"><strong>Refill belum dapat dibuat.</strong><ul><li v-for="(e,k) in f.errors" :key="k">{{e}}</li></ul></div><label>Vendor</label><select v-model="f.vendor_id" class="form-input" required @change="select"><option value="">Pilih Vendor</option><option v-for="x in vendors" :key="x.id" :value="x.id">{{x.code}} · {{x.name}}</option></select><div v-for="row in f.lines" :key="row.item_id" class="form-grid"><label><input v-model="row.enabled" type="checkbox"/> {{vendor.items.find(x=>x.id===row.item_id)?.code}} · {{vendor.items.find(x=>x.id===row.item_id)?.name}}</label><input v-model="row.quantity" class="form-input" type="number" min="1" step="1" :disabled="!row.enabled" required/></div><p v-if="vendor&&!f.lines.length">Tidak ada barang low stock.</p><textarea v-model="f.notes" class="form-input" placeholder="Catatan (opsional)"/><div class="form-actions"><Link :href="index_url" class="button button--secondary">Batal</Link><button class="button button--primary" :disabled="f.processing||!f.lines.some(x=>x.enabled)">Kirim Refill</button></div></form></section></div></template>
